namespace duckdb {

struct SortProjectionColumn {
	bool is_payload;
	idx_t layout_col_idx;
	idx_t output_col_idx;
};

} // namespace duckdb



namespace duckdb {

class SortLocalSinkState;
class SortGlobalSinkState;

class SortLocalSourceState;
class SortGlobalSourceState;

class SortedRun;
class SortedRunScanState;

class SortedRunMerger;
class SortedRunMergerLocalState;
class SortedRunMergerGlobalState;

class TupleDataLayout;
class ColumnDataCollection;

//! Class that sorts the data, follows the PhysicalOperator interface
class Sort {
	friend class SortLocalSinkState;
	friend class SortGlobalSinkState;

	friend class SortLocalSourceState;
	friend class SortGlobalSourceState;

	friend class SortedRun;
	friend class SortedRunScanState;

	friend class SortedRunMerger;
	friend class SortedRunMergerLocalState;
	friend class SortedRunMergerGlobalState;

public:
	Sort(ClientContext &context, const vector<BoundOrderByNode> &orders, const vector<LogicalType> &input_types,
	     vector<idx_t> projection_map, bool is_index_sort = false);

public:
	//! The client context
	ClientContext &context;

private:
	//! Key orders, expressions, and layout
	unique_ptr<Expression> create_sort_key;
	unique_ptr<Expression> decode_sort_key;
	shared_ptr<TupleDataLayout> key_layout;

	//! Projection map and payload layout (columns that also appear as key eliminated)
	vector<idx_t> payload_projection_map;
	shared_ptr<TupleDataLayout> payload_layout;

	//! Mapping from key/payload layouts to output columns
	vector<idx_t> input_projection_map;
	vector<SortProjectionColumn> output_projection_columns;

	//! Whether to force an approximate sort
	bool is_index_sort;

public:
	//===--------------------------------------------------------------------===//
	// Sink Interface
	//===--------------------------------------------------------------------===//
	unique_ptr<LocalSinkState> GetLocalSinkState(ExecutionContext &context) const;
	unique_ptr<GlobalSinkState> GetGlobalSinkState(ClientContext &context) const;
	SinkResultType Sink(ExecutionContext &context, DataChunk &chunk, OperatorSinkInput &input) const;
	SinkCombineResultType Combine(ExecutionContext &context, OperatorSinkCombineInput &input) const;
	SinkFinalizeType Finalize(ClientContext &context, OperatorSinkFinalizeInput &input) const;
	ProgressData GetSinkProgress(ClientContext &context, GlobalSinkState &gstate,
	                             const ProgressData source_progress) const;

public:
	//===--------------------------------------------------------------------===//
	// Source Interface
	//===--------------------------------------------------------------------===//
	unique_ptr<LocalSourceState> GetLocalSourceState(ExecutionContext &context, GlobalSourceState &gstate) const;
	unique_ptr<GlobalSourceState> GetGlobalSourceState(ClientContext &context, GlobalSinkState &sink) const;
	SourceResultType GetData(ExecutionContext &context, DataChunk &chunk, OperatorSourceInput &input) const;
	OperatorPartitionData GetPartitionData(ExecutionContext &context, DataChunk &chunk, GlobalSourceState &gstate,
	                                       LocalSourceState &lstate, const OperatorPartitionInfo &partition_info) const;
	ProgressData GetProgress(ClientContext &context, GlobalSourceState &gstate) const;

public:
	//===--------------------------------------------------------------------===//
	// Non-Standard Interface
	//===--------------------------------------------------------------------===//
	SourceResultType MaterializeColumnData(ExecutionContext &context, OperatorSourceInput &input) const;
	unique_ptr<ColumnDataCollection> GetColumnData(OperatorSourceInput &input) const;

	SourceResultType MaterializeSortedRun(ExecutionContext &context, OperatorSourceInput &input) const;
	unique_ptr<SortedRun> GetSortedRun(GlobalSourceState &global_state);
};

} // namespace duckdb


namespace duckdb {

enum class WindowMergeSortStage : uint8_t { INIT, COMBINE, FINALIZE, SORTED, FINISHED };

class WindowMergeSortTree;

class WindowMergeSortTreeLocalState : public LocalSinkState {
public:
	WindowMergeSortTreeLocalState(ExecutionContext &context, WindowMergeSortTree &index_tree);

	//! Add a chunk to the local sort
	void Sink(ExecutionContext &context, DataChunk &chunk, const idx_t row_idx,
	          optional_ptr<SelectionVector> filter_sel, idx_t filtered, InterruptState &interrupt);
	//! Sort the data
	void Finalize(ExecutionContext &context, InterruptState &interrupt);
	//! Process sorted leaf data
	virtual void BuildLeaves() = 0;

	//! The index tree we are building
	WindowMergeSortTree &window_tree;
	//! Thread-local sorting data
	optional_ptr<LocalSinkState> local_sink;
	//! Buffer for the sort data
	DataChunk sort_chunk;
	//! Build stage
	WindowMergeSortStage build_stage = WindowMergeSortStage::INIT;
	//! Build task number
	idx_t build_task;

private:
	void ExecuteSortTask(ExecutionContext &context, InterruptState &interrupt);
};

class WindowMergeSortTree {
public:
	using GlobalSortStatePtr = unique_ptr<GlobalSinkState>;
	using LocalSortStatePtr = unique_ptr<LocalSinkState>;

	WindowMergeSortTree(ClientContext &context, const vector<BoundOrderByNode> &orders,
	                    const vector<column_t> &order_idx, const idx_t count, bool unique = false);
	virtual ~WindowMergeSortTree() = default;

	virtual unique_ptr<LocalSinkState> GetLocalState(ExecutionContext &context) = 0;

	//! Make a local sort for a thread
	optional_ptr<LocalSinkState> InitializeLocalSort(ExecutionContext &context) const;

	//! Thread-safe post-sort cleanup
	virtual void Finished();

	//! Sort state machine
	bool TryPrepareSortStage(WindowMergeSortTreeLocalState &lstate);
	//! Build the MST in parallel from the sorted data
	void Build();

	//! The column indices for sorting
	const vector<column_t> order_idx;
	//! The sorted data schema
	vector<LogicalType> scan_types;
	vector<idx_t> scan_cols;
	//! The sort key columns
	vector<idx_t> key_cols;
	//! The sort specification
	unique_ptr<Sort> sort;
	//! The sorted data
	GlobalSortStatePtr global_sink;
	//! The resulting sorted data
	unique_ptr<ColumnDataCollection> sorted;
	//! Finalize guard
	mutable mutex lock;
	//! Local sort set
	mutable vector<LocalSortStatePtr> local_sinks;
	//! Finalize stage
	atomic<WindowMergeSortStage> build_stage;
	//! Tasks launched
	idx_t total_tasks = 0;
	//! Tasks launched
	idx_t tasks_assigned = 0;
	//! Tasks landed
	atomic<idx_t> tasks_completed;

	// Merge sort trees for various sizes
	// Smaller is probably not worth the effort.
	using MergeSortTree32 = MergeSortTree<uint32_t, uint32_t>;
	using MergeSortTree64 = MergeSortTree<uint64_t, uint64_t>;
	unique_ptr<MergeSortTree32> mst32;
	unique_ptr<MergeSortTree64> mst64;

protected:
	//! Find the starts of all the blocks
	//! Returns the total number of rows
	virtual idx_t MeasurePayloadBlocks();
};

} // namespace duckdb


